// ── CE QUE VINTED TRANSMET AUX IMPÔTS, compte par compte (6 octobre) ─────────
// La carte du registre annuel. Elle ne calcule RIEN : elle rend
// `seuilsVintedParCompte` (§11), et ses deux parties viennent du REGISTRE
// (`datees` et `aDater`, calculés par lui). Ton informatif : aucun rouge, aucun ambre (§7 —
// le rouge est pour deux paires sous un même numéro) ; un seuil atteint se dit
// par le MOT, en gras. Les nombres sont portés en `data-*` pour le banc.
// ⚠️ §7 : une cause, une phrase. La panne, la lecture en cours et l'estimation
//    des ventes pas encore datées se disent UNE fois au-dessus des lignes ; la
//    ligne d'un compte pas lu ne porte qu'un « — ».
// ⚠️ « Relire mes ventes » RELIT pour de vrai (`onRelire` vide le cache et
//    relance la lecture) : « rouvre l'écran Ventes » rouvrait le CACHE, qui
//    gardait l'échec — ou, avant la revue, le transformait en « 0 vente ».
function CarteSeuilsVinted({ annee, echoues, comptes, ecarte, nomDe, datees, aDater, onRelire }) {
  const [relit, setRelit] = useState(false);
  const tous = Array.isArray(comptes) ? comptes : [];
  const ko = new Set((Array.isArray(echoues) ? echoues : []).map(String));
  const R = seuilsVintedParCompte({ comptes: tous.map(a => ({ uid: a.vinted_user_id, nom: nomDe(a) })), ecarte, echoues: ko, datees, aDater, annee });
  const lignes = R.comptes;
  if (!lignes.length) return null;
  const nExclus = tous.filter(a => ecarte && ecarte(String(a.vinted_user_id))).length;
  const eur = (v) => Number(v).toFixed(2).replace('.', ',') + ' €';
  const pl = (n, mot) => `${n} ${mot}${n > 1 ? 's' : ''}`;
  const seuilEur = String(SEUIL_VINTED_EUR).replace(/\B(?=(\d{3})+(?!\d))/g, ' ') + ' €';
  const nomsDe = (uids) => uids.map(u => (lignes.find(r => r.uid === u) || {}).nom || u).join(', ');
  const avecTotal = lignes.length > 1;
  const verdictTxt = (r, ses) => {
    if (r.verdict === 'atteint') {
      const parN = r.n >= SEUIL_VINTED_VENTES, parE = r.cts > SEUIL_VINTED_EUR * 100;
      return `Seuil atteint : ${parN && parE ? `${SEUIL_VINTED_VENTES} ventes et plus de ${seuilEur}` : parN ? `${SEUIL_VINTED_VENTES} ventes` : `plus de ${seuilEur}`}.`;
    }
    if (r.verdict === 'atteintSi') return `Seuil atteint si ${r.nAd > 1 ? `${ses} ${r.nAd} ventes pas encore datées comptent` : `${ses === 'ses' ? 'sa' : 'la'} vente pas encore datée compte`} en ${annee} (${eur(r.eurAd)}).`;
    if (r.verdict === 'sous') return R.aCeJour ? `Sous les seuils à ce jour : encore ${pl(r.reste.n, 'vente')} ou ${eur(r.reste.cts / 100)} avant le seuil.` : 'Sous les seuils.';
    return '';
  };
  const aDaterTxt = (r) => (r.etat === 'lu' && r.nAd > 0 && r.verdict !== 'atteintSi') ? `+ ${pl(r.nAd, 'vente')} pas encore datée${r.nAd > 1 ? 's' : ''} (${eur(r.eurAd)})` : '';
  const pasLus = lignes.filter(r => r.etat === 'pasSu');
  const parVersements = pasLus.some(r => r.raison === 'versements');
  const ventesKO = pasLus.filter(r => r.raison === 'ventes');
  const enCours = lignes.some(r => r.etat === 'enCours');
  const estimation = lignes.some(r => r.etat === 'lu' && r.nAd > 0);
  const relire = async () => { if (relit || !onRelire) return; setRelit(true); try { await onRelire(); } catch (_) {} setRelit(false); };
  const ligne = (r, { total } = {}) => {
    const lu = r.etat === 'lu';
    const sous = lu ? verdictTxt(r, total ? 'les' : 'ses') : '';
    const plus = aDaterTxt(r);
    const attrs = total
      ? { 'data-seuils-total': annee, 'data-partiel': r.partiel ? r.manquants.join(',') : '' }
      : { 'data-seuil-compte': r.uid };
    return (
      <div key={total ? '_total' : r.uid} {...attrs} data-etat={r.etat} data-n={lu ? r.n : ''} data-eur={lu ? r.eur.toFixed(2) : ''} data-verdict={r.verdict || ''}
        data-adater={lu ? r.nAd : ''} data-eur-adater={lu ? r.eurAd.toFixed(2) : ''} data-reste-n={r.reste ? r.reste.n : ''} data-reste-eur={r.reste ? (r.reste.cts / 100).toFixed(2) : ''}
        style={{display:'flex',alignItems:'flex-start',gap:10,padding:'8px 0',borderTop:`${total ? 2 : 1}px solid ${C.border}`}}>
        <div style={{flex:1,minWidth:0}}>
          <div style={{fontSize:13,fontWeight:total?700:600,color:C.text,overflow:'hidden',textOverflow:'ellipsis',whiteSpace:total?'normal':'nowrap'}}>
            {total ? `Tous tes comptes ensemble${r.partiel ? ` · sans ${nomsDe(r.manquants)}` : ''}` : r.nom}
          </div>
          {sous && <div style={{fontSize:12,lineHeight:1.4,marginTop:2,color:r.verdict==='atteint'?C.text:C.muted,fontWeight:r.verdict==='atteint'?700:400}}>{sous}</div>}
          {plus && <div style={{fontSize:11,color:C.muted,lineHeight:1.4,marginTop:2}}>{plus}</div>}
        </div>
        <div style={{flexShrink:0,textAlign:'right',whiteSpace:'nowrap'}}>
          <div style={{fontSize:13,fontWeight:700,color:C.text}}>{lu ? `${r.partiel ? 'au moins ' : ''}${pl(r.n, 'vente')}` : '—'}</div>
          {lu && <div style={{fontSize:12,color:C.muted,marginTop:2}}>{eur(r.eur)}</div>}
        </div>
      </div>
    );
  };
  return (
    <div data-seuils-vinted={annee} data-a-ce-jour={R.aCeJour ? '1' : '0'} style={{border:`1px solid ${C.border}`,borderRadius:12,background:C.card,padding:'10px 12px',marginBottom:12}}>
      <div style={{fontSize:13,fontWeight:700,color:C.text,marginBottom:3}}>Ce que Vinted transmet aux impôts pour {annee}{R.aCeJour ? ' — à ce jour' : ''}</div>
      <div style={{fontSize:12,color:C.muted,lineHeight:1.45,marginBottom:8}}>
        Chaque année, Vinted transmet aux impôts les vendeurs qui font au moins {SEUIL_VINTED_VENTES} ventes ou plus de {seuilEur} dans l'année (directive européenne DAC7).
        {' '}Ici, tes ventes Vinted comptées dans ce registre{avecTotal ? <>, compte par compte puis tous ensemble : VRM ne sait pas si Vinted juge chaque compte à part ou additionne ceux d'une même personne.</> : '.'}
      </div>
      {estimation && (
        <div data-seuils-estimation style={{fontSize:11,color:C.muted,lineHeight:1.45,marginBottom:8}}>
          « Pas encore datées » : des ventes finalisées dont VRM n'a pas encore la date de versement. Elles sont rattachées à {annee} d'après leur date de vente — une estimation (Vinted verse en général dans les jours qui suivent), pas un chiffre du registre.
        </div>
      )}
      {enCours && <div data-seuils-encours style={{fontSize:12,color:C.muted,lineHeight:1.45,marginBottom:8}}>Lecture des ventes…</div>}
      {pasLus.length > 0 && (
        <div data-seuils-panne style={{display:'flex',alignItems:'flex-start',gap:10,flexWrap:'wrap',fontSize:12,color:C.text,lineHeight:1.45,marginBottom:8}}>
          <div style={{flex:'1 1 220px',minWidth:0}}>
            {parVersements
              ? "Les dates de versement de tes ventes Vinted n'ont pas pu être lues : impossible de dire où en sont tes comptes."
              : ventesKO.length === 1
                ? `Les ventes de ${ventesKO[0].nom} n'ont pas pu être lues : impossible de dire où en est ce compte.`
                : `Les ventes de ${ventesKO.length} comptes (${ventesKO.map(r => r.nom).join(', ')}) n'ont pas pu être lues : impossible de dire où ils en sont.`}
          </div>
          {onRelire && (
            <button type="button" data-relire-ventes onClick={relire} disabled={relit}
              style={{flexShrink:0,border:`1px solid ${C.border}`,borderRadius:12,background:'transparent',color:C.text,cursor:relit?'default':'pointer',fontSize:12,fontWeight:600,padding:'5px 11px',maxWidth:200,opacity:relit?0.6:1}}>
              {relit ? 'Lecture…' : 'Relire mes ventes'}
            </button>
          )}
        </div>
      )}
      {lignes.map(r => ligne(r))}
      {avecTotal && ligne(R.total, { total: true })}
      {nExclus > 0 && <div className="vrm-aide" style={{fontSize:11,color:C.muted,lineHeight:1.4,marginTop:4}}>Les comptes que tu as exclus de l'app ne sont pas comptés ici.</div>}
    </div>
  );
}

// ── VENDU / REÇU, JOUR PAR JOUR (4 octobre) ──────────────────────────────────
// Julien : « distingue les ventes que l'on fait en une journée et l'argent que
// l'on reçoit — je veux un graphique avec les ventes de la journée ».
// Deux séries, deux règles (`ventesFaites` · `ventesDeclarables`), même échelle.
// VENDU porte l'accent — la seule couleur (§7) ; REÇU reste à l'encre neutre.
// Un jour sans rien garde une trace grise : un trou se lirait comme une donnée
// manquante, pas comme un zéro. Quand le reçu n'a pas pu être lu (`recu:null`),
// sa barre n'est PAS dessinée — des zéros seraient un faux (§5).
// (Remplace `MiniBarres`, définie et jamais rendue — §4.11.)
function BarresVenduRecu({ jours, hauteur = 96 }) {
  const max = Math.max(1, ...jours.map(j => Math.max(j.vendu.eur, j.recu ? j.recu.eur : 0)));
  const eur = (x) => `${Math.round(x).toLocaleString('fr-FR')}\u00a0€`;
  const h = (v) => v > 0 ? Math.max(4, Math.round((v / max) * (hauteur - 4))) : 2;
  const totV = jours.reduce((a, j) => a + j.vendu.eur, 0);
  const totR = jours.every(j => j.recu) ? jours.reduce((a, j) => a + j.recu.eur, 0) : null;
  return (
    <div data-vendu-recu="">
      <div role="img" aria-label={`${jours.length} derniers jours : vendu ${eur(totV)}${totR != null ? ` · reçu ${eur(totR)}` : ''}`}
        style={{display:'flex',alignItems:'flex-end',gap:4,height:hauteur}}>
        {jours.map((j) => (
          <div key={j.cle} data-jour={j.cle} data-vendu={Math.round(j.vendu.eur * 100)} data-recu={j.recu ? Math.round(j.recu.eur * 100) : ''}
            title={`${j.long} · vendu ${eur(j.vendu.eur)} (${j.vendu.n} vente${j.vendu.n > 1 ? 's' : ''})${j.recu ? ` · reçu ${eur(j.recu.eur)}` : ''}`}
            style={{flex:1,minWidth:0,height:'100%',display:'flex',alignItems:'flex-end',justifyContent:'center',gap:2}}>
            <div style={{width:'44%',maxWidth:14,height:h(j.vendu.eur),background:j.vendu.eur > 0 ? C.accent : C.border,borderRadius:'3px 3px 0 0'}}/>
            {j.recu && <div style={{width:'44%',maxWidth:14,height:h(j.recu.eur),background:j.recu.eur > 0 ? C.muted : C.border,borderRadius:'3px 3px 0 0'}}/>}
          </div>
        ))}
      </div>
      <div style={{display:'flex',gap:4,marginTop:6,borderTop:`1px solid ${C.border}`,paddingTop:5}}>
        {jours.map((j, i) => {
          const auj = i === jours.length - 1;
          return <div key={j.cle} style={{flex:1,minWidth:0,textAlign:'center',fontSize:11,color:auj ? C.text : C.muted,fontWeight:auj ? 700 : 500,fontVariantNumeric:'tabular-nums'}}>{j.num}</div>;
        })}
      </div>
    </div>
  );
}

// Le prénom du bonjour. ⚠️ Un EMAIL n'est jamais un prénom (16 oct., vu sur sa
// capture iPhone : « Bon après-midi shopcancale35@gmail.com »). Ce qui contient
// « @ » ne se dit pas — « Bon après-midi » tout court : mieux vaut un blanc
// qu'un faux (§5). Le réglage n'est pas réécrit : on ne touche pas à SA donnée.
function prenomLisible(v) {
  const t = String(v == null ? '' : v).trim();
  return t.includes('@') ? '' : t;
}
// ⟦← App.jsx #190⟧

// ── LA SEMAINE EN BARRES (1er nov.) ───────────────────────────────────────────
// Julien : « je n'aime pas le graphique, il n'est pas beau ». La courbe lissée
// (cubique monotone) inventait une pente entre deux jours et plongeait sous un
// jour sans vente ; la série « reçu » en pointillé, sa légende et sa phrase
// d'explication encombraient la carte. Maintenant : UNE barre par jour passé,
// montant VENDU (date de la vente) — une seule série, aucune légende.
//   · la valeur au-dessus de la barre, seulement si elle tient dans sa colonne ;
//   · un « 0 » discret pour un jour passé sans vente ; rien après aujourd'hui ;
//   · aujourd'hui : son libellé en encre, souligné d'un trait cobalt ;
//   · barres à angles droits, posées sur une ligne de base, sans grille.
// Le « reçu » du jour reste PORTÉ (`data-recu`, et dans l'infobulle) : les bancs
// le lisent, il ne se dessine plus (une seule série par graphique). Dessinée à
// la LARGEUR MESURÉE et à une hauteur fixe (16 oct. : un viewBox étiré
// grossissait les chiffres avec l'écran).
function BarresSemaine({ jours }) {
  const ref = React.useRef(null);
  const [W, setW] = React.useState(340);
  const [Hdispo, setHdispo] = React.useState(0);
  const [compact, setCompact] = React.useState(() => { try { return window.matchMedia('(max-width:767px)').matches; } catch (_) { return false; } });
  React.useLayoutEffect(() => {
    const el = ref.current; if (!el) return undefined;
    // La hauteur aussi : côte à côte avec « Vendu », la carte est plus haute que
    // le graphique ; les barres prennent la place (jusqu'à 240 px) au lieu d'un vide.
    const mesure = () => { let mobile = false; try { mobile = window.matchMedia('(max-width:767px)').matches; } catch (_) {} const w = el.clientWidth, h = el.clientHeight; setCompact(mobile); if (w > 0) setW((v) => (Math.abs(v - w) > 1 ? w : v)); setHdispo((v) => (Math.abs(v - h) > 1 ? h : v)); };
    mesure();
    if (typeof ResizeObserver === 'undefined') return undefined;
    const ro = new ResizeObserver(mesure); ro.observe(el);
    return () => ro.disconnect();
  }, []);
  const Hmin = compact ? 136 : 148;
  const H = Math.round(Math.max(Hmin, Math.min(240, Hdispo || 0))), haut = 18, bas = 34;
  const base = H - bas, plot = base - haut;
  const col = W / 7;
  const larg = Math.max(10, Math.min(compact ? 28 : 44, col * 0.5));
  const X = (i) => col * i + col / 2;
  const vus = jours.filter((j) => !j.futur);
  const max = Math.max(1, ...vus.map((j) => j.vendu.eur));
  const totV = vus.reduce((a, j) => a + j.vendu.eur, 0);
  const eur = (x) => `${Math.round(x).toLocaleString('fr-FR')}\u00a0€`;
  const mono = { fontFamily: 'var(--vrm-police-mono)', fontVariantNumeric: 'tabular-nums' };
  return (
    <div ref={ref} className="vrm-jc-barres" style={{ width: '100%', minHeight: Hmin }}>
      <svg data-courbe-semaine="" data-style-courbe="barres" width={W} height={H} viewBox={`0 0 ${W} ${H}`} role="img" aria-label={`Semaine en cours : ${eur(totV)} vendus`} style={{ display: 'block' }}>
        <line x1={0} x2={W} y1={base + 0.5} y2={base + 0.5} stroke={C.border} strokeWidth="1"/>
        {jours.map((j, i) => {
          const v = j.futur ? null : j.vendu.eur;
          const h = v == null ? 0 : Math.max(v > 0 ? 3 : 0, (v / max) * plot);
          const txt = v == null ? '' : String(Math.round(v));
          // La valeur ne s'écrit que si elle tient dans sa colonne (≈ 6,8 px par chiffre à 11 px).
          const tient = txt.length * 6.8 <= col - 4;
          const encre = j.auj ? C.text : C.muted;
          return (
            <g key={j.cle} data-jour={j.cle} data-vendu={j.futur ? '' : Math.round(j.vendu.eur * 100)} data-recu={j.futur || !j.recu ? '' : Math.round(j.recu.eur * 100)} data-auj={j.auj ? '' : undefined}>
              {!j.futur && <title>{`${j.long} · vendu ${eur(j.vendu.eur)} (${j.vendu.n} vente${j.vendu.n > 1 ? 's' : ''})${j.recu ? ` · reçu ${eur(j.recu.eur)}` : ''}`}</title>}
              {v != null && <rect data-barre="" x={X(i) - larg / 2} y={base - h} width={larg} height={h} fill={C.accent}/>}
              {v != null && tient && <text x={X(i)} y={base - h - 6} textAnchor="middle" fontSize={v > 0 ? 11 : 10} fill={v > 0 ? C.text : C.muted} opacity={v > 0 ? 1 : 0.7} style={mono}>{txt}</text>}
              <text x={X(i)} y={H - 18} textAnchor="middle" fontSize="11" fontWeight={j.auj ? 700 : 500} fill={encre} opacity={j.futur ? 0.5 : 1}>{j.jour.toLowerCase()}</text>
              <text x={X(i)} y={H - 5} textAnchor="middle" fontSize="11" fill={encre} opacity={j.futur ? 0.5 : 1} style={mono}>{j.num}</text>
              {j.auj && <rect x={X(i) - 9} y={H - 2} width={18} height={2} fill={C.accent}/>}
            </g>
          );
        })}
      </svg>
    </div>
  );
}
