        <div className="vrm-w-feuille-tete" style={{ borderBottom: `1px solid ${C.border}` }}>
          <div style={{ flex: 1, minWidth: 0 }}>
            <div style={{ fontSize: 17, fontWeight: 700 }}>Ajouter un widget</div>
            <div className="vrm-aide" style={{ fontSize: 13, color: C.muted }}>Il se place à la fin — glisse-le ensuite où tu veux.</div>
          </div>
          <Bouton variante="secondaire" data-widgets-fermer="" onClick={onClose} style={{ flexShrink: 0 }}>Fermer</Bouton>
        </div>
