    for (const r of repartis) if (r.t) { const k = suiviDeLigne(r.t); if (k) nEmailConnus.add(k); }
    for (const x of aVerifier) if (x.t) { const k = suiviDeLigne(x.t); if (k) nEmailConnus.add(k); }
    const extra = [];
