  // Changer de filtre, de compte ou de période VIDE la sélection (rien ne reste coché hors de l'écran).
  const serieVentes = useSelectionSerie(ordreVentesSerie, { nom: 'ventes', vue: JSON.stringify([vFilter, selEff || '', periode || null, !!showHidden]) });
  const actionsSerieVentes = () => {
    const parTx = new Map(ventesAffichees.map(o => [String(o.transaction_id), o]));
    const lignes = (cles) => cles.map(k => parTx.get(k)).filter(Boolean);
    const annulee = (o) => classifyOrderStatus(o.status) === 'cancelled';
    // UNE règle par action, lue par le bouton (« 2 sur 3 », grisé à 0) ET par l'action (`trierSerie`).
    let pretsMemo = null;
    const prets = () => pretsMemo || (pretsMemo = new Set(lignesLotTous().filter(l => l.cochable !== false).map(l => String(l.cle))));
    const peutImprimer = (o) => annulee(o) ? 'annulée' : estParti(o) ? 'déjà partie' : prets().has(String(o.transaction_id)) ? true : 'pas de bordereau prêt';
    return [
      // (17 nov., nouveau design) `plein` : le libellé du bouton plein de la barre (le nombre = cochées ET imprimables = imprimées) ;
      // `raisonZero` : ce que dit le menu « ⋯ » quand rien de la sélection ne s'y prête.
      { k: 'imprimer', libelle: 'Imprimer', icone: 'printer', variante: 'primaire', plein: (n) => tr('v2s.imprimer', { n }), raisonZero: tr('v2s.zero.imprimer'), portee: (cles) => portee(lignes(cles), peutImprimer), faire: async (cles) => {
        // Les bordereaux prêts du lot « Tout imprimer » (même clé : le n° de transaction).
        const { ok, pasFaits } = trierSerie(lignes(cles), peutImprimer);
        if (ok.length) await batchBordereaux(new Set(ok.map(o => String(o.transaction_id))));
        return resumeSerie({ faits: ok, pasFaits }, { un: 'bordereau préparé', plusieurs: 'bordereaux préparés' });
      } },
      // (20 nov., chasse-bugs-2 — décision « 4 oui ») « Je dépose » en série retiré : le dépôt est constaté par le suivi du transporteur.
      { k: 'exporter', libelle: 'Exporter', icone: 'doc', faire: (cles) => {
        const L = lignes(cles);
        const csv = csvDe(['Date', 'Compte', 'Article', 'N°', 'Prix (€)', 'État', 'N° de transaction'],
          L.map(o => { const e = effEntry(o); return [o.date && Number.isFinite(new Date(o.date).getTime()) ? new Date(o.date).toLocaleDateString('fr-FR') : '', o._acc ? accNameOf(o._acc) : '', o.title || '', (e && e.numero) || '', o.price && o.price.amount != null ? Number(o.price.amount).toFixed(2).replace('.', ',') : '', o.status_title || o.status || '', String(o.transaction_id)]; }));
        telechargerFichier(csv, `ventes-${dateLocaleISO()}.csv`, 'text/csv;charset=utf-8');
        return resumeSerie({ faits: L, pasFaits: [] }, { un: 'vente exportée', plusieurs: 'ventes exportées' });
      } },
      { k: 'facture', libelle: 'Facture Pro', icone: 'receipt', faire: async (cles) => {
        const L = lignes(cles);
        const txDe = (o) => String(o._fromEmail ? o._txMail : o.transaction_id);
        const m = await import('../FacturePro.jsx');
        const r = await m.envoyerFacturesSerie(DEPS_FACTURE, L.map(txDe), sales.items);
        if (!r) return { annule: true };
        return resumeSerie(r, { un: 'facture envoyée', plusieurs: 'factures envoyées' });
      } },
    ];
  };
  const groupeFactureCle = useMemo(() => groupeFacture.map((v) => v.tx + ':' + (v.commandes || []).length).join(','), [groupeFacture]);
  // Une recherche ou un changement de filtre repart du haut : sinon on garderait
  // « 240 affichées » sur une liste qui n'en compte plus que trois.
  const filtresLimiteVentes=useRef(null);
  useEffect(() => { const sig=JSON.stringify([vFilter,ordSearchDiff,periode,showHidden]);if(filtresLimiteVentes.current!==null&&filtresLimiteVentes.current!==sig)setVentesMax(60);filtresLimiteVentes.current=sig; }, [vFilter, ordSearchDiff, periode, showHidden]);
  // Un seul compte dans la liste ⇒ le nommer sur chaque carte ne distingue rien
  // (§7 : « compte julatace3535 » ×5). Il ne reste que s'il y en a plusieurs.
  // ⚠️ `_acc` est un OBJET, pas une chaîne (§ le fix #449) : `String(obj)` donne
  //    « [object Object] » pour toutes les ventes → Set de taille 1 → le compte
  //    n'était JAMAIS nommé sur une carte de vente, même avec neuf comptes. On
  //    lit l'identifiant, comme `annUnCompte` juste en dessous (§11).
  const ventesUnCompte = useMemo(() => new Set(ventesAffichees.map(x => String((x._acc && x._acc.vinted_user_id) || x._uid || ''))).size <= 1, [ventesAffichees]);

  // Annonces filtrées (recherche titre/marque/N°) + triées. Sert à retrouver vite
  // une paire quand il y en a beaucoup, comme dans les outils pros de revente.
  // Annonces à retirer AUTOMATIQUEMENT car une VENTE est confirmée par email.
  // ⚠️ (11 nov., revue robustesse) PAR IDENTITÉ SEULEMENT (§5) : l'e-mail porte sa
  // transaction → l'annonce que Vinted lui rattache (`txnItem`), ou un bordereau relié
  // par identité (`bordForItem`). Plus jamais titre + taille (src/venduesParEmail.js).
  const emailSoldIds = useMemo(() => venduesParEmail({ enLigne: listings.items, ventesEmail: emailSales, itemDeTx: txnItem, numeros, bordPour: (emailBords && emailBords.length) ? bordForItem : null }),
  // eslint-disable-next-line react-hooks/exhaustive-deps
  [emailSales, emailBords, listings.items, numeros, txnItem]);
  // On MÉMORISE la liste des annonces auto-retirées (vendues d'après les emails).
  // Pourquoi : le tableau de bord compte « annonces en ligne » AVANT que cet
  // onglet ait tourné ; sans cette mémoire il comptait des paires déjà vendues
  // et affichait un total supérieur à celui de l'onglet Annonces. Il lit
  // maintenant la même exclusion. Se recalcule seul à chaque passage ici.
  useEffect(() => {
    if (!listings.items) return;
    // ⚠️ « RIEN LU » ≠ « RIEN » (revue du 26 oct.). `emailSoldIds` est RECONSTRUIT
    //    à partir des emails de vente ET des bordereaux ; si une de ces deux
    //    sources n'a PAS pu être lue (`null`), la reconstruction est incomplète
    //    et RÉTRÉCIRAIT la liste persistée — on réécrirait `vinted_annonces_email_sold`
    //    (clé SYNCHRONISÉE → poussée au nuage, tous appareils) amputée, et une
    //    paire déjà vendue redeviendrait « en ligne » → reproposée ailleurs →
    //    DOUBLE VENTE. On ne réécrit QUE quand les deux sources sont lues.
    if (emailSales === null || emailBords === null) return;
    // (11 nov.) L'identité vient de « transaction → annonce » : tant qu'elle n'est
    // pas LUE, la reconstruction rétrécirait la liste (« rien lu » ≠ « rien »).
    if (TXN_ETATS_LU !== true) return;
    const arr = [...emailSoldIds];
    const prev = load('vinted_annonces_email_sold', []) || [];
    if (arr.length !== prev.length || arr.some(x => !prev.includes(x))) save('vinted_annonces_email_sold', arr);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [emailSoldIds, listings.items, txnItem]);
  // Base commune des annonces : tout ce qui est réellement « en ligne chez moi ».
  // Un compte détecté BLOQUÉ par Vinted a des annonces moissonnées périmées (le
  // compte est fermé) → on les retire, comme celles d'un compte masqué à la main.
  // ⚠️ C'est CETTE liste que doivent utiliser la grille ET le bandeau de stats :
  // sinon le compteur annonce un nombre que la grille ne montre pas.
  // (`pairsLost` — paires déclarées PERDUES — est déclarée plus haut, à côté de
  //  `listings` : les annonces masquées présentes la lisent pendant le rendu.)

  // ── ANNONCES DISPARUES SANS VENTE (compte masqué / annonce retirée) ───────
  // Vinted masque parfois un compte entier pendant plusieurs jours. Ses annonces
  // s'évaporent de la moisson : elles ne sont ni vendues, ni supprimées par toi.
  // Sans traitement, ces paires restent « numérotées » dans le vide — on ne sait
  // plus si elles sont vendues, perdues ou juste invisibles.
  //
  // Règle : une paire est « disparue » si elle a un numéro, qu'elle n'est plus
  // dans le wardrobe, qu'AUCUNE vente ne lui correspond, et que son compte a
  // bien répondu au dernier chargement (sinon c'est juste un chargement raté).
  // On ne décide rien à sa place : on la SIGNALE, et c'est toi qui tranches.
  const disparues = useMemo(() => {
    if (!listings.items || !sales.items) return [];
    const decisionsCycle = lireObjet(CYCLE_DECISIONS);
    const onlineIds = new Set(); const presentAcc = new Set();
    for (const it of listings.items) { onlineIds.add(String(it.id)); const u = String(it._acc?.vinted_user_id || ''); if (u) presentAcc.add(u); }
    // Numéros qui correspondent à une vente (à n'importe quel stade) : ces
    // paires sont parties normalement, elles n'ont rien à faire ici.
    const vendus = new Set();
    for (const o of (sales.items || [])) {
      const e = saleOv[String(o.transaction_id)];
      const n = cleNum(e && e.numero); if (n) vendus.add(n);   // (11 nov.) par cleNum
      // ⚠️ `vendus.add('t:' + titre)` VIVAIT ICI, et RIEN ne le lisait — le test
      //    par titre avait été retiré (voir le commentaire plus bas), la ligne
      //    qui l'alimentait était restée. Même famille que le tiroir `Nav` : du
      //    code mort qu'un relecteur « rebranche » un jour en croyant réparer un
      //    oubli, et le rapprochement par ressemblance revient (§5).
    }
    // (23 oct.) Une annonce MASQUÉE par Vinted n'a pas « disparu » : VRM sait où
    // elle est (toujours chez lui, `<masquees-regle>`). Elle a SON bloc, avec
    // « Elle n'est plus là » — la dire ici aussi, c'était deux voix contraires
    // sur la même paire (« disparue — Retirer » et « présente, à vérifier »).
    const masqueesIds = new Set((listings.masquees || []).map((it) => String(it.id)));
    const out = [];
    for (const k in numeros) {
      const e = numeros[k]; const raw = String((e && e.numero) || '').trim();
      if (!raw) continue;
      if (onlineIds.has(String(k))) continue;                       // toujours en ligne
      if (masqueesIds.has(String(k))) continue;                     // masquée par Vinted : son bloc
      if (annonceDeclareePartie(k, numeros, pairsLost)) continue;   // déclarée partie (par identité)
      if (!presentAcc.has(String((e && e.accountId) || ''))) continue; // compte pas rafraîchi
      if (soldManual.has(String(k))) continue;                      // marquée vendue à la main
      if (emailSoldIds.has(String(k))) continue;                    // vendue d'après les emails
      if (vendus.has(cleNum(raw))) continue;                        // numéro porté par une vente
      // ⚠️ Le test « même TITRE qu'une vente » a été retiré : avec plusieurs paires
      //    au même libellé, une seule vente les masquait TOUTES de l'audit — donc
      //    une paire réellement perdue passait inaperçue. Le titre n'est pas une
      //    identité. Il est REMPLACÉ par celle-ci : Vinted ne supprime pas une
      //    annonce vendue, il la ferme en « vendue » — et ça se lit par IDENTIFIANT.
      if (venduesVinted.has(String(k))) continue;                   // Vinted dit : vendue
      if (pairsLost[raw]) continue;                                 // déjà déclarée perdue
      // (3 nov.) Il a répondu « Toujours chez moi » à « N°x supprimé de Vinted »
      // (Ma journée, src/cycleArticle.js) : une seule voix, la sienne.
      { const ch = (decisionsCycle[String(k)] || {}).choix; if (ch === CHOIX_CYCLE.CHEZ_MOI || ch === CHOIX_CYCLE.REMISE) continue; }   // (9 nov.) « Remise en ligne » : chez lui aussi
      out.push({ id: String(k), e, numero: raw });
    }
    out.sort((a, b) => (parseInt(a.numero, 10) || 0) - (parseInt(b.numero, 10) || 0));
    return out;
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [listings.items, listings.masquees, sales.items, numeros, saleOv, soldManual, emailSoldIds, pairsLost, venduesVinted]);

  // Compte entièrement muet : il a des paires numérotées mais renvoie ZÉRO
  // annonce. C'est la signature d'un compte masqué par Vinted (ou fermé).
  const comptesMuets = useMemo(() => {
    if (!listings.items) return [];
    const parAcc = {};
    for (const it of listings.items) { const u = String(it._acc?.vinted_user_id || ''); if (u) parAcc[u] = (parAcc[u] || 0) + 1; }
    const attendus = {};
    for (const k in numeros) { const u = String(numeros[k]?.accountId || ''); if (u) attendus[u] = (attendus[u] || 0) + 1; }
    const out = [];
    for (const u in attendus) {
      if (parAcc[u]) continue;                       // il répond → rien à signaler
      if (acctOff(u)) continue;                      // déjà masqué à la main / bloqué
      // 5.167 : on ne juge « muet » que sur une lecture de MOINS de 24 h — une
      // lecture plus vieille ne dit rien (ses annonces sont « à confirmer »).
      const lu = Number(listings.lues && listings.lues[u]);
      if (!(lu > 0 && Date.now() - lu <= ENLIGNE_FRAIS_MS)) continue;
      const acc = accounts.find(a => String(a.vinted_user_id) === u);
      if (!acc) continue;                            // compte déconnecté, pas notre sujet
      out.push({ uid: u, acc, nb: attendus[u] });
    }
    return out;
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [listings.items, listings.lues, numeros, accounts, hiddenAccts, blockedAccts]);

  // ⚠️⚠️ UNE PAIRE VENDUE QUI TRAÎNE ENCORE « EN LIGNE » — ET LE TITRE DÉSIGNAIT
  // LA MAUVAISE. Vinted laisse parfois l'annonce avec `is_closed:false` après la
  // vente. La règle était : *une vente de moins de 60 jours dont le titre est
  // UNIQUE parmi les annonces en ligne*, avec pour seule garde « un titre en
  // double ne retire rien ». Cette garde comptait les annonces EN LIGNE — pas
  // les ventes : deux paires identiques, il en vend une, il n'en reste qu'une en
  // ligne… donc le titre redevient « unique », et **la paire qu'il a encore
  // disparaît de son écran Annonces**.
  //
  // Mesuré le 15 septembre sur ses **65 annonces en ligne** : **5 étaient
  // retirées**, et **aucune des cinq n'est prouvée vendue**. Pour quatre d'entre
  // elles Vinted dit lui-même quelle annonce est partie — et c'est une **AUTRE**
  // à chaque fois : « Adidas Spezial noir taille 35,5 » a **3 ventes**, qui
  // pointent vers 3 annonces différentes ; celle qui restait en ligne était la
  // quatrième paire, bien réelle. C'est §2.4 mot pour mot (« même avec
  // 50 articles identiques, tu ne dois pas pouvoir te tromper »), et une annonce
  // cachée est une paire qu'il ne peut plus numéroter, ni cocher pour Leboncoin,
  // ni tarifer.
  //
  // ⇒ On retire sur l'IDENTITÉ (`identiteAnnonce` : transaction → item_id, sinon
  //   la photo — les deux voies certaines, le titre en est exclu depuis toujours).
  //   Mesuré après : **5 retirées à tort → 0**, et **0 paire prouvée vendue n'est
  //   laissée en ligne** (la règle du titre n'en attrapait aucune que l'identité
  //   rate). Quand l'identité ne dit rien, on ne retire pas : mieux vaut un blanc
  //   qu'un faux.
  const annoncesVendues = useMemo(() => {
    const ids = new Set();
    for (const o of (sales.items || [])) {
      if (classifyOrderStatus(o.status) === 'cancelled') continue;   // retour/remboursement : la paire revient
      const ts = o.date ? Date.parse(o.date) : NaN;
      if (!isNaN(ts) && (Date.now() - ts) / 86400000 > 60) continue;
      const id = identiteAnnonce(o); if (id) ids.add(String(id));
      // (11 nov., lot ventes-lot) Une vente en LOT : CHAQUE article de SA transaction est parti
      // (identifiant d'annonce donné par Vinted, jamais le titre).
      const l = lotDeVente(o);
      if (l && l.lu) for (const a of l.articles) if (a.item) ids.add(String(a.item));
    }
    return ids;
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [sales.items, txnItem, numeros, lotsTx, lotLiens]);
  // (3 nov., choix n° 3) Les N° remis en stock après un retour (« Retour reçu ? » → « Remettre en
  // stock ») : posés par l'effet qui suit `retoursSuivis` (plus bas), lus par la publication ci-dessous.
  // (13 nov., point 29) `null` = pas encore su (la publication attend : une lecture en cours ne
  // retire jamais un article revenu des paires présentes) ; sinon `{ articles, aNumeroter }` en JSON.
  const [numsRemisCle, setNumsRemisCle] = useState(null);
  const numsRemisPoseRef = React.useRef(null);   // la dernière valeur posée (l'effet plus bas ne repose jamais la même)
  useEffect(() => {
    // Revue de la 5.167 : les annonces « à confirmer » sont peut-être encore sur
    // l'étagère — leur numéro reste PHYSIQUE (une seule source des paires
    // présentes, `porteursNum`/`numDoublons`, §11).
    // 22 oct. : et les masquées par Vinted (`annoncesPresentes`).
    // 28 oct. : et les paires EN VENTE sur eBay ou Leboncoin, même absentes de
    // Vinted (`articlesAutresPlateformes`, par leur N° lu par identité), sauf un
    // N° dont la vente Vinted est prouvée et le colis parti. Publiées aussi avec
    // leur titre et leur photo (`autres`) : le Stock les propose « à ranger ».
    const presentes = annoncesPresentes;
    if (!presentes.length) return;   // rien de sûr à publier (Vinted pas encore lu : on ne publie pas eBay seul)
    if (!sales.items) return;
    if (numsRemisCle === null) return;   // (13 nov.) les retours en stock pas encore sus : on attend
    const vivants = new Set();
    for (const it of presentes) { const n = String((numeros[it.id] || {}).numero || '').trim(); if (n) vivants.add(n); }
    for (const o of (sales.items || [])) {
      if (!needsBordereau(o.status)) continue;
      const n = String((saleOv[String(o.transaction_id)] || {}).numero || '').trim(); if (n) vivants.add(n);
    }
    // (3 nov.) Un article REMIS EN STOCK après un retour (son tap) est chez lui, avec SON N°.
    // (13 nov., point 29) …et un article REVENU tout seul (retour prouvé remboursé, `retourRevenuSeul`).
    let retoursStock = [], retoursANumeroter = 0;
    try { const rs = JSON.parse(numsRemisCle); retoursStock = Array.isArray(rs.articles) ? rs.articles : []; retoursANumeroter = Number(rs.aNumeroter) || 0; } catch (_) {}
    for (const a of retoursStock) if (a && a.numero) vivants.add(String(a.numero));
    const clesVivants = new Set([...vivants].map(cleNum));
    const vendusPartis = new Set();
    for (const id of annoncesVendues) { const k = cleNum((numeros[id] || {}).numero); if (k && !clesVivants.has(k)) vendusPartis.add(k); }
    // (11 nov., lot ventes-lot) Un article de lot relié par SON clic porte son N° sans fiche d'annonce.
    for (const o of (sales.items || [])) { if (classifyOrderStatus(o.status) === 'cancelled') continue; const l = lotDeVente(o); if (l && l.lu) for (const a of l.articles) if (a.num && a.par === 'main') { const k = cleNum(a.num); if (k && !clesVivants.has(k)) vendusPartis.add(k); } }
    const { articles, sansNumero } = articlesAutresPlateformes({ ebay: ebayStock || [], lbc: lbcStock || [], cle: cleNum, vendusPartis });
    const autres = [];
    for (const a of articles) { const surVinted = clesVivants.has(a.cle); if (!surVinted) { vivants.add(a.numero); clesVivants.add(a.cle); } autres.push({ numero: a.numero, title: a.title, photo: a.photo, plateformes: a.plateformes, vinted: surVinted }); }
    const liste = [...vivants].sort((a,b)=>(+a||0)-(+b||0));
    try {
      const avant = load('vinted_nums_physiques', null);
      const memeChose = avant && Array.isArray(avant.nums) && avant.nums.length === liste.length && avant.nums.every((x,i)=>x===liste[i])
        && JSON.stringify(avant.autres || []) === JSON.stringify(autres) && JSON.stringify(avant.sansNumero || null) === JSON.stringify(sansNumero)
        && JSON.stringify(avant.retours || []) === JSON.stringify(retoursStock) && (Number(avant.retoursANumeroter) || 0) === retoursANumeroter;
      if (!memeChose) save('vinted_nums_physiques', { nums: liste, autres, sansNumero, retours: retoursStock, retoursANumeroter, at: Date.now() });
    } catch (_) {}
  }, [annoncesPresentes, sales.items, numeros, saleOv, annoncesVendues, ebayStock, lbcStock, numsRemisCle, lotsTx, lotLiens]);
  const articlesVendusFavoris=useMemo(()=>{
    const ids=new Set([...soldManual,...venduesVinted].map(String));
    for(const vente of sales.items||[]){
      if(classifyOrderStatus(vente.status)==='cancelled')continue;
      const id=txnItem[String(vente.transaction_id)];
      if(id)ids.add(String(id));
    }
    return ids;
  },[soldManual,venduesVinted,sales.items,txnItem]);
  // (28 oct.) PUBLIÉ pour l'écran Stock (grille de photos) — §11, la preuve de
  // vente a UN seul propriétaire : ici. On publie les NUMÉROS des paires
  // prouvées vendues (par identité, jamais le titre — c'est `annoncesVendues`),
  // le Stock CONSOMME pour allumer un halo sur la paire à sortir. Clé LOCALE,
  // recalculable (comme `vinted_nums_physiques`). ⚠️ « pas su » (ventes
  // illisibles) ⇒ on ne publie pas, on garde la dernière valeur connue ; une
  // vente annulée/remboursée sort d'`annoncesVendues` ⇒ n'est plus publiée ⇒
  // halo éteint et la paire RESTE (jamais de retrait automatique).
  useEffect(() => {
    if (!sales.items) return;                                   // pas su : on ne touche pas
    const nums = new Set();
    annoncesVendues.forEach((id) => { const n = cleNum((numeros[id] || {}).numero); if (n) nums.add(n); });
    const liste = [...nums].sort();
    try {
      const avant = load('vrm_stock_vendus', null);
      const meme = avant && Array.isArray(avant.nums) && avant.nums.length === liste.length && avant.nums.every((x, i) => x === liste[i]);
      if (!meme) save('vrm_stock_vendus', { nums: liste, at: Date.now() });
    } catch (_) {}
  }, [annoncesVendues, numeros, sales.items]);
  // (6 nov.) PUBLIÉ pour l'inventaire du Stock (src/inventaire.js) : les N° portés
  // par deux paires présentes (`conflitsNum`, §11 — un seul propriétaire, ici), le
  // seul rouge de l'inventaire. Clé LOCALE, recalculable. Ventes ou annonces pas
  // lues, ou liste lue en partie ⇒ on ne publie pas (« pas su » : la dernière valeur reste).
  useEffect(() => {
    if (!sales.items || listings.loading || listings.incomplet || !Array.isArray(listings.items)) return;
    const liste = [...new Set(conflitsNum.map((c) => cleNum(c.numero)).filter(Boolean))].sort();
    try {
      const avant = load('vrm_num_doublons', null);
      const meme = avant && Array.isArray(avant.nums) && avant.nums.join(',') === liste.join(',');
      if (!meme) save('vrm_num_doublons', { nums: liste, at: Date.now() });
    } catch (_) {}
  }, [conflitsNum, sales.items, listings.items, listings.loading, listings.incomplet]);
  // Le tri des comptes et des ventes, le MÊME pour la grille et pour les annonces
  // « à confirmer » (5.167) : une annonce d'un compte exclu, ou prouvée vendue,
  // n'est ni dans l'une ni dans l'autre.
  const garderAnnonce = (it) => {
      // ⚠️ UNE ANNONCE DOIT VENIR D'UN COMPTE QUI EXISTE ENCORE. `acctOffOf`
      // teste `_acc.vinted_user_id` : quand ce compte a été supprimé, l'annonce
      // portait un compte introuvable, `acctOff('')` répondait « non masqué »
      // et elle restait affichée — une paire d'un compte qui ne figure même
      // plus dans la liste des comptes. Même règle que l'extension (§5.20) :
      // un compte existe s'il a des jetons, pas parce qu'il reste des données.
      const uidIt = String((it && it._acc && it._acc.vinted_user_id) || '');
      if (!uidIt || !accountUids.has(uidIt)) return false;
      // ⚠️ COMPTE BANNI PAR VINTED (403) → ses annonces ne sont plus « en ligne »
      //    (Julien : « dès qu'un compte est ban, enlève l'annonce en ligne »).
      //    Le constructeur `liveStats` les écartait DÉJÀ (`skipAcc` = blocked ||
      //    hidden) : l'écran Annonces le faisait pas → deux nombres pour la même
      //    notion (§11). On aligne. Ça ne touche PAS la compta/ventes (un compte
      //    banni a quand même vendu) : `acctOffOf` reste inchangé.
      //    `isBanni` ne marque que sur un vrai 403 (jamais un 401 « session
      //    expirée »), et l'auto-réparation rallume un compte re-capté — donc
      //    aucun compte sain n'est écarté à tort.
      if (blockedAccts.has(uidIt)) return false;
      // (19 nov., lot compte-bloque) Compte bloqué par Vinted, ses annonces en pause (SON choix) : hors de « en ligne »
      //    et des totaux, comptées « en pause · compte bloqué » (`annEnPause`). Ses ventes, elles, restent partout.
      if (pauseCB.has(uidIt)) return false;
      if (venteOffOf(it) || soldManual.has(String(it.id))) return false;
      if (!showEmailSold && emailSoldIds.has(String(it.id))) return false;
      // Vendue d'après VINTED LUI-MÊME (identité, jamais le titre).
      if (!showEmailSold && annoncesVendues.has(String(it.id))) return false;
      return true;
  };
  const annBase = useMemo(() => (listings.items || []).filter(garderAnnonce),
  // eslint-disable-next-line react-hooks/exhaustive-deps
  [listings.items, soldManual, emailSoldIds, showEmailSold, blockedAccts, hiddenAccts, annoncesVendues, accountUids, pauseCB]);
  // Les annonces d'un compte pas relu depuis 24 h : ni en ligne, ni disparues —
  // dites UNE fois au-dessus de la grille, repliées (`FraicheurAnnonces`).
  const annAConfirmer = useMemo(() => (listings.aConfirmer || []).filter(garderAnnonce),
  // eslint-disable-next-line react-hooks/exhaustive-deps
  [listings.aConfirmer, soldManual, emailSoldIds, showEmailSold, blockedAccts, hiddenAccts, annoncesVendues, accountUids]);
  // ── NUMÉROS À VÉRIFIER SUR LES CARTONS (18 octobre) ─────────────────────
  // Les paires en ligne (ou à confirmer) numérotées automatiquement pendant la
  // panne de synchronisation : leur N° a pu être redonné (`PANNE_NUMEROS`).
  // 22 oct. : les paires MASQUÉES par Vinted sont sur l'étagère, numérotées
  // elles aussi pendant la panne — même filtre que la grille (`garderAnnonce`).
  const annMasquees = useMemo(() => masqueesSurEtagere.filter(garderAnnonce),
  // eslint-disable-next-line react-hooks/exhaustive-deps
  [masqueesSurEtagere, soldManual, emailSoldIds, showEmailSold, blockedAccts, hiddenAccts, annoncesVendues, accountUids]);
  // (9 nov., lot F) LES PAIRES PRÉSENTES pour « Tu as déjà N paires de ce modèle en
  // stock » (src/dejaEnStock.js) : en ligne (`annBase`) + masquées sur l'étagère
  // (`annMasquees`) — la même étagère que la grille. Une LECTURE : rien n'est écrit.
  // « Depuis » = la date « Ajouté il y a… » relevée, sinon la date Vinted (`listedAgeDays`).
  const stockPourModele = useMemo(() => {
    const out = [];
    for (const it of [...annBase, ...annMasquees]) {
      if (!it || it.id == null) continue;
      const d = listingDates[String(it.id)];
      const ts = d && d.ts ? Number(d.ts) : (it.createdTs != null ? (it.createdTs < 1e12 ? it.createdTs * 1000 : it.createdTs) : null);
      out.push({ id: String(it.id), num: String((numeros[String(it.id)] || {}).numero || ''), titre: it.title || '', marque: it.brand || '', taille: it.size || '', photo: it.photo || null, depuisMs: Number.isFinite(ts) ? ts : null });
    }
    return out;
  }, [annBase, annMasquees, listingDates, numeros]);
  // (23 oct.) TOUTES les masquées numérotées, chacune avec son geste : celles
  // encore comptées sur l'étagère (« Elle n'est plus là ») et celles qu'il a
  // déclarées parties (« Elle est encore là » répare une erreur). Sans ce bloc,
  // une masquée qui n'est ni en double ni « à vérifier » n'avait AUCUN chemin
  // pour être déclarée partie (compte sans annonce en ligne : pas même
  // « disparues »).
