  // ── URGENCE DES COLIS — UNE SEULE DÉFINITION ────────────────────────────
  // Le calcul vivait dans le bloc de rendu du bandeau rouge ; le bandeau du
  // haut ne pouvait donc pas savoir si l'urgence couvrait TOUS les colis ou
  // seulement une partie — d'où deux blocs consécutifs annonçant le même
  // ensemble (« 3 colis à envoyer » puis « 3 à poster en priorité »).
  // Même source que la liste : les colis que Vinted attend, avec leur délai.
  const nAPoster = () => expeditions().filter(e => !(e.o && isShipDone(e.o))).length;
  const urgenceColis = () => {
    let overdue = 0, aVerifier = 0, today = 0, tomorrow = 0, pressePret = 0, presseAttente = 0;
    for (const e of expeditions()) {
      if (e.o && isShipDone(e.o)) continue;
      if (e.dl == null) continue;
      // (revue du 22 oct.) Une date ESTIMÉE dépassée n'est pas un retard (la
      // vraie limite tombe jusqu'à 3 j plus tard) : « à vérifier sur Vinted ».
      if (e.dl < 0) { if (e.lim && e.lim.depasse && !e.lim.retard) aVerifier++; else overdue++; }
      else if (e.dl === 0) today++; else if (e.dl === 1) tomorrow++; else continue;
      // ⚠️ OÙ SONT-ILS ? La liste se groupe sur CE QU'IL PEUT FAIRE (prêts à
      //    imprimer d'abord, puis en attente de bordereau) et l'urgence n'est
      //    que le tri À L'INTÉRIEUR de chaque groupe. Le bandeau affirmait
      //    pourtant « les plus urgents sont en haut de la liste » : faux dès
      //    que l'urgent attend encore son bordereau — vu en capture le
      //    8 septembre, le seul « à poster demain » était dix cartes plus bas,
      //    dans le second groupe. La structure avait été corrigée, la phrase
      //    qui la décrit était restée en arrière (même défaut que la carte
      //    URSSAF). On compte donc les deux, ici, sur la même source.
      if (e.pret) pressePret++; else presseAttente++;
    }
    const parts = [];
    if (overdue) parts.push(`${overdue} en retard`);
    if (aVerifier) parts.push(`${aVerifier} à vérifier sur Vinted (date estimée dépassée)`);
    if (today) parts.push(`${today} aujourd'hui`);
    if (tomorrow) parts.push(`${tomorrow} demain`);
    return { overdue, aVerifier, today, tomorrow, total: overdue + aVerifier + today + tomorrow, danger: overdue > 0 || aVerifier > 0 || today > 0, parts,
             pressePret, presseAttente };
  };
  // La phrase du bandeau d'urgence — elle DÉCRIT la liste, elle ne la promet
  // pas. Trois cas, parce qu'il y a trois situations réelles.
  const ouSontLesPresses = (u) => {
    // (19 oct.) La liste se trie maintenant par vente la plus récente : la
    // phrase ne promet plus « en haut », elle dit où le voir (sur sa ligne).
    // (5 nov., chantier D) Les groupes « Prêts à imprimer » / « En attente de leur bordereau » n'existent
    // plus (la liste est rangée par transporteur, le plus pressé d'abord) : la phrase disait où
    // chercher dans des groupes absents. Elle dit l'ordre réel, une fois.
    // (9 nov., soir, lot AJ) La liste est rangée du plus récent au plus ancien (décision de Julien) :
    // les pressés se lisent sur leur carte (date limite, ambre si proche), plus « en haut ».
    if (!u.presseAttente) return 'sa date limite est écrite sur sa carte.';
    return u.presseAttente > 1
      ? `sa date limite est écrite sur sa carte ; ${u.presseAttente} attendent encore leur bordereau.`
      : 'sa date limite est écrite sur sa carte ; 1 attend encore son bordereau.';
  };

  // La saisie en série : l'écriture de tout prix tapé (`ecrirePrixTape`, src/prixAuNumerotage.js).
  // (6 nov.) Avant : le texte brut (« 25 € env. » enregistré tel quel) et un champ vidé
  // écrivait '' en effaçant le lien vers l'achat. Vide ⇒ rien ; illisible ⇒ rien, dit.
  const setBuyForKey = (key, val) => { ecrirePrixTape(key, val); };
  // ── (14 nov., lot argent-choix — proposition 75) « COLLER UN TABLEAU » (src/collerPrixAchat.js) ──
  // Les fiches d'un N° (clé `cleNum`) et leur prix d'achat par LA règle de l'app (`prixAchatDe`).
  // L'écriture est celle d'un prix TAPÉ (`ecriturePrixSaisi`, comme la saisie en série), en UNE
  // fois : relue sur les fiches du moment (comparer-et-échanger), jamais sans base chargée.
  const [collerOuvert, setCollerOuvert] = useState(false);
  const fichesCollage = React.useCallback((cle) => Object.entries(numeros || {})
    .filter(([, e]) => e && e.numero != null && String(e.numero).trim() && cleNum(e.numero) === cle)
    .map(([k, e]) => ({ key: k, numero: String(e.numero).trim(), prix: prixAchatDe(e, buyByNum), titre: String(e.title || ''), photo: e.photo || '' })), [numeros, buyByNum]);
  const enregistrerCollage = (ecritures) => {
    if (!isCloudReady()) { toast(tr('ac.coller.pasLu')); return null; }
    const { garder, changees } = verifierAvantEcriture(ecritures, fichesCollage);
    const lus = garder.map((w) => ({ w, e: ecriturePrixSaisi(w.prix) })).filter((x) => x.e.etat === 'ok');
    if (lus.length) {
      pointAvant('collage', `Collage de ${lus.length} prix d’achat`);   // revenir en arrière (Paramètres)
      setNumeros((prev) => { const u = { ...prev }; for (const { w, e } of lus) u[w.key] = { ...(u[w.key] || {}), ...e.patch }; save('vinted_annonce_numeros', u); return u; });
      setBuyByNum((prev) => { const u = { ...prev }; for (const { w, e } of lus) u[w.numero] = e.patch.buyPrice; save('vinted_buyprice_by_num', u); return u; });
    }
    return { ecrits: lus.length, changees: changees + (garder.length - lus.length) };
  };
  const [showReport, setShowReport] = useState(false);
  const [reportMonth, setReportMonth] = useState(() => { const d=new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`; });
  const [moisOuvert, setMoisOuvert] = useState(false);
  const [reportAnnee, setReportAnnee] = useState(() => new Date().getFullYear());
  const ymOf = (dstr) => { if(!dstr) return null; const d=new Date(dstr); if(isNaN(d)) return null; return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`; };
  // ⚠️ Les mois qui portent vraiment des ventes FINALISÉES — c'est ce qu'on
  // déclare. Sert à ouvrir le rapport sur un mois qui a du contenu (le 2 du
