            {avecAbsent ? <div className="vrm-eg-absent" data-qr-plein-absent={ck}><strong>{titreQrAbsent(ck)}</strong><span>{qrView.qrOu}</span></div> : <p className="vrm-eg-mode">{phraseMode}</p>}
